    #[inline(always)]
    fn parse_plus_54_ll1_body(&mut self, i: u32) -> Option<(u32, SPPFNodeId)> {
        let mut j = i;
        let (body_end, body_node) = (self.parse_alt_19_ll1(j, None))?;
        j = body_end;
        let left_extent = i;
        let mut current = self.add_nonterminal_node(NonterminalNode {
            nonterminal_id: NonterminalId(302),
            return_slot: SlotId(2107),
            span: Span {
                left_extent,
                right_extent: j,
            },
            child: body_node,
            ambiguous: false,
        });
        #[allow(clippy::while_let_loop)]
        loop {
            let Some((pos_0, node_0)) = self.parse_alt_19_ll1(j, None) else {
                break;
            };
            j = pos_0;
            current = self.create_intermediate_node_ll1(
                SlotId(2105),
                left_extent,
                pos_0,
                current,
                node_0,
            );
            current = self.add_nonterminal_node(NonterminalNode {
                nonterminal_id: NonterminalId(302),
                return_slot: SlotId(2105),
                span: Span {
                    left_extent,
                    right_extent: j,
                },
                child: current,
                ambiguous: false,
            });
        }
        Some((j, current))
    }
    #[inline(always)]
    fn parse_star_34_ll1(
        &mut self,
        i: u32,
        _failure_context: Option<SlotId>,
    ) -> Option<(u32, SPPFNodeId)> {
        #[cfg(feature = "instrument")]
        self.ll1_call_log.push((NonterminalId(303), i));
        let Some(matched) = self.scanner.longest_match(&FIRST_SET_STAR_34, i) else {
            return {
                let epsilon_node_id = self.get_or_create_epsilon_node(i);
                Some((
                    i,
                    self.add_nonterminal_node(NonterminalNode {
                        nonterminal_id: NonterminalId(303),
                        return_slot: SlotId(2110),
                        span: Span {
                            left_extent: i,
                            right_extent: i,
                        },
                        child: epsilon_node_id,
                        ambiguous: false,
                    }),
                ))
            };
        };
        match matched {
            TerminalId(52) | TerminalId(51) => {
                let mut j = i;
                let right_child = {
                    let start = j;
                    let (end, node) = self.parse_plus_54_ll1(start, Some(SlotId(2109)))?;
                    j = end;
                    node
                };
                let left_extent = i;
                let current = right_child;
                Some((
                    j,
                    self.add_nonterminal_node(NonterminalNode {
                        nonterminal_id: NonterminalId(303),
                        return_slot: SlotId(2109),
                        span: Span {
                            left_extent,
                            right_extent: j,
                        },
                        child: current,
                        ambiguous: false,
                    }),
                ))
            }
            _ => unreachable!("LL(1) dispatch covers every terminal in FIRST_SET"),
        }
    }
    fn get_gss_node_expression(&self, input_index: u32, p: i32) -> Option<GssNodeId> {
        self.gss_nodes_index_expression
            .get(&(input_index, p))
            .copied()
    }
    fn get_gss_node_lambda(&self, input_index: u32, p: i32) -> Option<GssNodeId> {
        self.gss_nodes_index_lambda.get(&(input_index, p)).copied()
    }
    fn get_gss_node_lambda_body(&self, input_index: u32, p: i32) -> Option<GssNodeId> {
        self.gss_nodes_index_lambda_body
            .get(&(input_index, p))
            .copied()
    }
    fn add_gss_node_expression(&mut self, input_index: u32, p: i32, gss_node_id: GssNodeId) {
        self.gss_nodes_index_expression
            .insert((input_index, p), gss_node_id);
    }
    fn add_gss_node_lambda(&mut self, input_index: u32, p: i32, gss_node_id: GssNodeId) {
        self.gss_nodes_index_lambda
            .insert((input_index, p), gss_node_id);
    }
    fn add_gss_node_lambda_body(&mut self, input_index: u32, p: i32, gss_node_id: GssNodeId) {
        self.gss_nodes_index_lambda_body
            .insert((input_index, p), gss_node_id);
    }
    fn get_or_create_epsilon_node(&mut self, i: u32) -> SPPFNodeId {
        if let Some(existing) = self.epsilon_nodes[i as usize] {
            record!(self, TerminalNodeFound, existing);
            return existing;
        }
        let span = Span::new(i, i);
        let terminal_id = TerminalId(160);
        record!(self, TerminalNodeCreated, terminal_id, span);
        let node_id = self
            .sppf_nodes
            .push(SPPFNode::Terminal(TerminalNode { terminal_id, span }));
        self.epsilon_nodes[i as usize] = Some(node_id);
        node_id
    }
    #[inline(never)]
    fn add_failure_at_farthest_index(
        &mut self,
        input_index: u32,
        slot_id: SlotId,
        gss_node_id: Option<GssNodeId>,
        kind: GLLFailureKind,
    ) {
        if input_index > self.failures_index {
            self.failures.clear();
            self.failures_index = input_index;
        }
        self.failures.push(GLLFailure {
            input_index,
            slot_id,
            gss_node_id,
            kind,
        });
    }
